+    output_hashes: Object.fromEntries(['replay-fixture.json', 'transformations.json', 'provenance.json', 'installed-recorder-receipts.json', 'drain.json', 'accepted-cursors.json'].map(f => [f, sha(readFileSync(`${output}/${f}`))])),
